/**
 * Extrude WGS84 footprints with Earcut caps and outer/inner walls.
 * STL axes are X=east, Y=up, Z=south; h is the top elevation, min_height the base.
 * Input: one rectangular Polygon with properties { h: 10 } and origin [lng, lat].
 * Output: one solid b0, closed triangles, metre bounds and conversion statistics.
 */
import earcut from 'earcut'

const EARTH_RADIUS = 6378137 // WGS84 semi-major axis, metres
const D2R = Math.PI / 180

/* ------------------------------------------------------------------------ */
/* Projection helpers                                                        */
/* ------------------------------------------------------------------------ */

function lngLatToMercator(lng, lat) {
  const clamped = Math.max(-89.9999, Math.min(89.9999, lat))
  return [EARTH_RADIUS * lng * D2R, EARTH_RADIUS * Math.log(Math.tan(Math.PI / 4 + (clamped * D2R) / 2))]
}

/**
 * Build a function mapping [lng, lat] to local [east, north] metres around
 * `origin`.
 *
 * @param {[number, number]} origin  [lng, lat]
 * @param {"local"|"web-mercator"} mode
 */
export function makeProjector(origin, mode = 'local') {
  if (!origin.every(Number.isFinite) || Math.abs(origin[0]) > 180 || Math.abs(origin[1]) >= 90)
    throw new Error('Origin must contain finite longitude/latitude away from the poles')
  const [lng0, lat0] = origin
  if (mode === 'web-mercator') {
    const [ox, oy] = lngLatToMercator(lng0, lat0)
    return (c) => {
      const [mx, my] = lngLatToMercator(c[0], c[1])
      return [mx - ox, my - oy]
    }
  }
  // Equirectangular projection centred on the origin. For a city-sized
  // domain (a few km) the error is well below 0.1 %.
  const kx = EARTH_RADIUS * D2R * Math.cos(lat0 * D2R)
  const ky = EARTH_RADIUS * D2R
  return (c) => [(c[0] - lng0) * kx, (c[1] - lat0) * ky]
}

/**
 * Inverse of `makeProjector("local")`: local [east, north] metres -> [lng, lat].
 */
export function makeUnprojector(origin) {
  if (!origin.every(Number.isFinite) || Math.abs(origin[0]) > 180 || Math.abs(origin[1]) >= 90)
    throw new Error('Origin must contain finite longitude/latitude away from the poles')
  const [lng0, lat0] = origin
  const kx = EARTH_RADIUS * D2R * Math.cos(lat0 * D2R)
  const ky = EARTH_RADIUS * D2R
  return (p) => [lng0 + p[0] / kx, lat0 + p[1] / ky]
}

/* ------------------------------------------------------------------------ */
/* Geometry helpers                                                          */
/* ------------------------------------------------------------------------ */

function signedArea(ring) {
  let area = 0
  for (let i = 0, n = ring.length; i < n; i++) {
    const [x1, y1] = ring[i]
    const [x2, y2] = ring[(i + 1) % n]
    area += x1 * y2 - x2 * y1
  }
  return area / 2
}

/**
 * Remove the closing vertex and consecutive duplicates. Returns null when the
 * ring does not contain at least three distinct points.
 */
function cleanRing(ring, eps = 1e-6) {
  const out = []
  for (let i = 0; i < ring.length; i++) {
    const p = ring[i]
    if (!p || !isFinite(p[0]) || !isFinite(p[1])) continue
    const last = out[out.length - 1]
    if (!last || Math.abs(last[0] - p[0]) > eps || Math.abs(last[1] - p[1]) > eps) {
      out.push([p[0], p[1]])
    }
  }
  while (
    out.length > 1 &&
    Math.abs(out[0][0] - out[out.length - 1][0]) <= eps &&
    Math.abs(out[0][1] - out[out.length - 1][1]) <= eps
  ) {
    out.pop()
  }
  return out.length >= 3 ? out : null
}

function orient(ring, counterClockwise) {
  const ccw = signedArea(ring) > 0
  return ccw === counterClockwise ? ring : ring.slice().reverse()
}

function fmt(n) {
  // 4 decimals (0.1 mm) is plenty for metres and keeps files small.
  const v = +n.toFixed(4)
  return v === 0 ? '0' : String(v)
}

/* ------------------------------------------------------------------------ */
/* STL writer                                                                */
/* ------------------------------------------------------------------------ */

class SolidWriter {
  constructor(bounds) {
    this.lines = []
    this.chunks = [] // joined blocks of ~4k lines: keeps memory flat on huge exports
    this.bounds = bounds
    this.triangles = 0
  }

  flush(force = false) {
    if (this.lines.length >= 4096 || (force && this.lines.length)) {
      this.chunks.push(this.lines.join('\n') + '\n')
      this.lines.length = 0
    }
  }

  /** Points are given in local [east, north, up] metres. */
  facet(a, b, c) {
    // Map into STL frame: X = east, Y = up, Z = -north
    const A = [a[0], a[2], -a[1]]
    const B = [b[0], b[2], -b[1]]
    const C = [c[0], c[2], -c[1]]

    const ux = B[0] - A[0],
      uy = B[1] - A[1],
      uz = B[2] - A[2]
    const vx = C[0] - A[0],
      vy = C[1] - A[1],
      vz = C[2] - A[2]
    let nx = uy * vz - uz * vy
    let ny = uz * vx - ux * vz
    let nz = ux * vy - uy * vx
    const len = Math.sqrt(nx * nx + ny * ny + nz * nz)
    if (!(len > 1e-12)) return // degenerate triangle
    nx /= len
    ny /= len
    nz /= len

    const bd = this.bounds
    for (const P of [A, B, C]) {
      if (P[0] < bd.x_min) bd.x_min = P[0]
      if (P[0] > bd.x_max) bd.x_max = P[0]
      if (P[1] < bd.y_min) bd.y_min = P[1]
      if (P[1] > bd.y_max) bd.y_max = P[1]
      if (P[2] < bd.z_min) bd.z_min = P[2]
      if (P[2] > bd.z_max) bd.z_max = P[2]
    }

    this.lines.push(
      `  facet normal ${fmt(nx)} ${fmt(ny)} ${fmt(nz)}`,
      '    outer loop',
      `      vertex ${fmt(A[0])} ${fmt(A[1])} ${fmt(A[2])}`,
      `      vertex ${fmt(B[0])} ${fmt(B[1])} ${fmt(B[2])}`,
      `      vertex ${fmt(C[0])} ${fmt(C[1])} ${fmt(C[2])}`,
      '    endloop',
      '  endfacet',
    )
    this.triangles++
  }

  begin(name) {
    this.lines.push(`solid ${name}`)
  }

  end(name) {
    this.lines.push(`endsolid ${name}`)
    this.flush()
  }
}

/**
 * Write a vertical prism. `rings[0]` is the exterior (CCW), the rest are holes
 * (CW). Every ring must already be cleaned and oriented.
 */
function writePrism(writer, rings, base, top) {
  // Walls
  for (const ring of rings) {
    for (let i = 0, n = ring.length; i < n; i++) {
      const p = ring[i]
      const q = ring[(i + 1) % n]
      const p0 = [p[0], p[1], base],
        q0 = [q[0], q[1], base]
      const p1 = [p[0], p[1], top],
        q1 = [q[0], q[1], top]
      writer.facet(p0, q0, q1)
      writer.facet(p0, q1, p1)
    }
  }
  // Roof and floor
  const flat = earcut.flatten(rings)
  const tris = earcut(flat.vertices, flat.holes, flat.dimensions)
  const verts = flat.vertices
  for (let i = 0; i < tris.length; i += 3) {
    const ia = tris[i] * 2,
      ib = tris[i + 1] * 2,
      ic = tris[i + 2] * 2
    const a = [verts[ia], verts[ia + 1]]
    const b = [verts[ib], verts[ib + 1]]
    const c = [verts[ic], verts[ic + 1]]
    // earcut returns CCW triangles for a CCW exterior -> normal up
    writer.facet([a[0], a[1], top], [b[0], b[1], top], [c[0], c[1], top])
    writer.facet([a[0], a[1], base], [c[0], c[1], base], [b[0], b[1], base])
  }
}

/**
 * Terrain patch: a triangle whose three top vertices have individual
 * elevations (properties a, b, c) and a flat floor at 0.
 */
function writeTerrain(writer, ring, heights) {
  const tri = orient(ring.slice(0, 3), true)
  const h = (i) => (isFinite(heights[i]) ? heights[i] : heights[0])
  const top = tri.map((p, i) => [p[0], p[1], h(i)])
  const bottom = tri.map((p) => [p[0], p[1], 0])
  for (let i = 0; i < 3; i++) {
    const j = (i + 1) % 3
    writer.facet(bottom[i], bottom[j], top[j])
    writer.facet(bottom[i], top[j], top[i])
  }
  writer.facet(top[0], top[1], top[2])
  writer.facet(bottom[0], bottom[2], bottom[1])
}

/* ------------------------------------------------------------------------ */
/* Public API                                                                */
/* ------------------------------------------------------------------------ */

function toNumber(v) {
  if (v === null || v === undefined || v === '') return NaN
  const n = typeof v === 'number' ? v : parseFloat(String(v).replace(',', '.'))
  return isFinite(n) ? n : NaN
}

function bboxCenter(collection) {
  let minX = Infinity,
    minY = Infinity,
    maxX = -Infinity,
    maxY = -Infinity
  const visit = (coords) => {
    if (typeof coords[0] === 'number') {
      if (coords[0] < minX) minX = coords[0]
      if (coords[0] > maxX) maxX = coords[0]
      if (coords[1] < minY) minY = coords[1]
      if (coords[1] > maxY) maxY = coords[1]
    } else {
      coords.forEach(visit)
    }
  }
  for (const f of collection.features || []) {
    if (f && f.geometry && f.geometry.coordinates) visit(f.geometry.coordinates)
  }
  if (!isFinite(minX)) return [0, 0]
  return [(minX + maxX) / 2, (minY + maxY) / 2]
}

/**
 * Convert a GeoJSON FeatureCollection of (Multi)Polygons in WGS84 into an
 * ASCII STL string.
 *
 * @param {object} collection GeoJSON FeatureCollection (lng/lat)
 * @param {object} [options]
 * @param {[number,number]} [options.origin]      [lng, lat] of STL (0,0,0). Defaults to bbox centre.
 * @param {"local"|"web-mercator"} [options.projection="local"]
 * @param {string}  [options.heightProperty="h"]  property holding the building height (m)
 * @param {string}  [options.baseProperty="min_height"] property holding the base elevation (m)
 * @param {number}  [options.defaultHeight]       used when the height is missing/invalid (feature skipped if omitted)
 * @param {number}  [options.minHeight=0.1]       features lower than this are skipped
 * @param {string}  [options.solidPrefix="b"]     solid name prefix (b0, b1, ...)
 * @param {string}  [options.extraStl=""]         raw ASCII STL appended verbatim (not included in bounds)
 * @param {Array}   [options.extraSolids=[]]      parsed STL solids ({name, positions}) already in the STL frame
 *                                                (X east, Y up, Z south, metres relative to the same origin);
 *                                                written as additional solids, normals recomputed, bounds included
 * @param {boolean} [options.hasTerrain=false]    passed through in the result
 * @returns {{stl:string, bounds:object, origin:[number,number], solids:Array, stats:object}}
 */
function createConverter(collection, options = {}) {
  const opts = Object.assign(
    {
      origin: null,
      projection: 'local',
      heightProperty: 'h',
      baseProperty: 'min_height',
      defaultHeight: undefined,
      minHeight: 0.1,
      solidPrefix: 'b',
      extraStl: '',
      extraSolids: [],
      hasTerrain: false,
    },
    options,
  )

  if (!collection || collection.type !== 'FeatureCollection' || !Array.isArray(collection.features)) {
    throw new Error('geojsonToStl: expected a GeoJSON FeatureCollection')
  }

  let origin = opts.origin
  if (!origin || !isFinite(toNumber(origin[0])) || !isFinite(toNumber(origin[1]))) {
    origin = bboxCenter(collection)
  } else {
    origin = [toNumber(origin[0]), toNumber(origin[1])]
  }
  const project = makeProjector(origin, opts.projection)

  const bounds = {
    x_min: Infinity,
    x_max: -Infinity,
    y_min: Infinity,
    y_max: -Infinity,
    z_min: Infinity,
    z_max: -Infinity,
  }
  const writer = new SolidWriter(bounds)
  const solids = []
  const skipped = []
  let terrainCount = 0

  const projectRings = (rings) => {
    const out = []
    for (let r = 0; r < rings.length; r++) {
      const ring = cleanRing(rings[r].map(project))
      if (!ring) {
        if (r === 0) return null // exterior is degenerate -> skip polygon
        continue // ignore degenerate hole
      }
      out.push(orient(ring, r === 0))
    }
    return out
  }

  const processFeature = (feature, index) => {
    if (!feature || !feature.geometry) {
      skipped.push({ index, reason: 'no geometry' })
      return
    }
    const props = feature.properties || {}
    const geom = feature.geometry
    const id = feature.id !== undefined ? feature.id : props.id

    // Terrain triangle (a, b, c elevations)
    if (geom.type === 'Polygon' && props.a !== undefined) {
      const rings = projectRings(geom.coordinates)
      if (!rings) {
        skipped.push({ index, reason: 'degenerate terrain ring' })
        return
      }
      const heights = [toNumber(props.a), toNumber(props.b), toNumber(props.c)]
      const name = `t${index}`
      const before = writer.triangles
      writer.begin(name)
      writeTerrain(writer, rings[0], heights)
      writer.end(name)
      solids.push({ name, featureIndex: index, id, type: 'terrain', triangles: writer.triangles - before })
      terrainCount++
      return
    }

    let height = toNumber(props[opts.heightProperty])
    if (!isFinite(height)) height = toNumber(opts.defaultHeight)
    if (!isFinite(height) || height < opts.minHeight) {
      skipped.push({ index, reason: 'missing or too small height' })
      return
    }
    let base = toNumber(props[opts.baseProperty])
    if (!isFinite(base) || base < 0 || base >= height) base = 0

    let polygons
    if (geom.type === 'Polygon') polygons = [geom.coordinates]
    else if (geom.type === 'MultiPolygon') polygons = geom.coordinates
    else {
      skipped.push({ index, reason: `unsupported geometry ${geom.type}` })
      return
    }

    polygons.forEach((polygon, part) => {
      const rings = projectRings(polygon)
      if (!rings) {
        skipped.push({ index, part, reason: 'degenerate polygon' })
        return
      }
      const name = geom.type === 'MultiPolygon' ? `${opts.solidPrefix}${index}_${part}` : `${opts.solidPrefix}${index}`
      const before = writer.triangles
      writer.begin(name)
      writePrism(writer, rings, base, height)
      writer.end(name)
      solids.push({
        name,
        featureIndex: index,
        part,
        id,
        type: 'building',
        height,
        base,
        triangles: writer.triangles - before,
      })
    })
  }

  const finish = () => {
    // Additional pre-built solids (e.g. STL models imported on the map)
    for (const extra of opts.extraSolids || []) {
      const p = extra.positions
      if (!p || p.length < 9) continue
      const name = String(extra.name || `stl${solids.length}`).replace(/\s+/g, '_')
      const before = writer.triangles
      writer.begin(name)
      for (let i = 0; i < p.length; i += 9) {
        // STL frame (x, up, south) -> local (east, north, up)
        writer.facet([p[i], -p[i + 2], p[i + 1]], [p[i + 3], -p[i + 5], p[i + 4]], [p[i + 6], -p[i + 8], p[i + 7]])
      }
      writer.end(name)
      solids.push({ name, type: 'stl', triangles: writer.triangles - before, source: extra.source })
    }

    writer.flush(true)
    if (opts.extraStl && typeof opts.extraStl === 'string' && opts.extraStl.trim()) {
      writer.chunks.push(opts.extraStl.trim() + '\n')
    }
    const chunks = writer.chunks

    Object.keys(bounds).forEach((k) => {
      if (!isFinite(bounds[k]) || bounds[k] === 0) bounds[k] = 0 // also normalises -0
    })

    return {
      /** Array of text blocks — pass directly to `new Blob(chunks)` for large files. */
      chunks,
      /** Whole file as one string (convenience; avoid for very large exports). */
      get stl() {
        return chunks.join('')
      },
      bounds,
      origin,
      projection: opts.projection,
      solidPrefix: opts.solidPrefix,
      hasTerrain: opts.hasTerrain || terrainCount > 0,
      solids,
      stats: {
        features: collection.features.length,
        solids: solids.length,
        buildings: solids.filter((x) => x.type === 'building').length,
        imported: solids.filter((x) => x.type === 'stl').length,
        terrain: terrainCount,
        triangles: writer.triangles,
        skipped,
      },
    }
  }

  return { processFeature, finish, features: collection.features }
}

/**
 * Convert a GeoJSON FeatureCollection of (Multi)Polygons in WGS84 into an
 * ASCII STL string (synchronous).
 *
 * @param {object} collection GeoJSON FeatureCollection (lng/lat)
 * @param {object} [options]
 * @param {[number,number]} [options.origin]      [lng, lat] of STL (0,0,0). Defaults to bbox centre.
 * @param {"local"|"web-mercator"} [options.projection="local"]
 * @param {string}  [options.heightProperty="h"]  property holding the building height (m)
 * @param {string}  [options.baseProperty="min_height"] property holding the base elevation (m)
 * @param {number}  [options.defaultHeight]       used when the height is missing/invalid (feature skipped if omitted)
 * @param {number}  [options.minHeight=0.1]       features lower than this are skipped
 * @param {string}  [options.solidPrefix="b"]     solid name prefix (b0, b1, ...)
 * @param {string}  [options.extraStl=""]         raw ASCII STL appended verbatim (not included in bounds)
 * @param {Array}   [options.extraSolids=[]]      parsed STL solids ({name, positions}) already in the STL frame
 * @param {boolean} [options.hasTerrain=false]    passed through in the result
 * @returns {{stl:string, bounds:object, origin:[number,number], solids:Array, stats:object}}
 */
export default function geojsonToStl(collection, options = {}) {
  const conv = createConverter(collection, options)
  conv.features.forEach((f, i) => conv.processFeature(f, i))
  return conv.finish()
}

/**
 * Same as `geojsonToStl` but processes features in batches and yields to the
 * event loop between batches, so the UI stays responsive on large exports and
 * the operation can report progress or be cancelled.
 *
 * @param {object} collection
 * @param {object} options            see geojsonToStl
 * @param {object} [control]
 * @param {number}   [control.batchSize=200]      features per batch
 * @param {function} [control.onProgress]         called with (done, total)
 * @param {function} [control.shouldCancel]       return true to abort (rejects with Error "cancelled")
 */
export async function geojsonToStlAsync(collection, options = {}, control = {}) {
  const conv = createConverter(collection, options)
  const total = conv.features.length
  const batch = Math.max(1, control.batchSize || 200)
  for (let i = 0; i < total; i++) {
    conv.processFeature(conv.features[i], i)
    if ((i + 1) % batch === 0 || i + 1 === total) {
      if (control.onProgress) control.onProgress(i + 1, total)
      if (control.shouldCancel && control.shouldCancel()) {
        const err = new Error('cancelled')
        err.cancelled = true
        throw err
      }
      await new Promise((r) => setTimeout(r, 0))
    }
  }
  return conv.finish()
}

/**
 * Build the CityFFD `domain.txt` text from a converter result.
 * The domain is padded by four times the tallest building on every side,
 * The remaining columns use the provided simulation settings.
 */
/** Input: bounds x=0..10, y=0..5, z=-10..0. Output: a 16-column header and padded domain row. */
export function buildDomainText(result, extra = ' 1 10 500 0.1 0.17 0.2 0 36 10 0') {
  const b = result.bounds
  const pad = Math.max(0, b.y_max) * 4
  const header =
    'x_min x_max y_min y_max z_min z_max L_scale L_ref output_step DT pow_u Cs Thermal CityBEM_iter total_num_iter GEMdata'
  if (!(b.y_max > Math.max(0, b.y_min))) {
    throw new Error('Domain export needs geometry with a positive height above the origin.')
  }
  const values = [
    Math.round(b.x_min + 1) - pad,
    Math.round(b.x_max - 1) + pad,
    fmt(b.y_min),
    fmt(b.y_max * 4),
    Math.round(b.z_min + 1) - pad,
    Math.round(b.z_max - 1) + pad,
  ]
  // The legacy 1 m inset/rounding can invert bounds on small STL models; keep their real extent plus padding.
  if (values[0] >= values[1]) [values[0], values[1]] = [b.x_min - pad, b.x_max + pad]
  if (values[4] >= values[5]) [values[4], values[5]] = [b.z_min - pad, b.z_max + pad]
  const row = values.join(' ')
  return `${header}\n${row}${extra}`
}

/**
 * Build one CityBEM row per building feature; year/type use selected properties.
 * Input: solid b0 referencing feature 0 with id 12, year 2000, type "office".
 * Output: header and a tab-separated row "b0\t\t12\t\t2000\t\toffice\n".
 */
export function buildBuildingInfoText(result, collection, yearKey, typeKey, withCenters = false) {
  const lines = [
    withCenters
      ? 'Building_stl\tBuilding_osm\tyear\ttype\tlat_center\tlng_center'
      : 'Building_stl\tBuilding_osm\tyear\ttype',
  ]
  const seen = new Set()
  const prefix = result.solidPrefix || 'b'
  for (const s of result.solids) {
    if (s.type !== 'building') continue
    if (seen.has(s.featureIndex)) continue // one row per feature, even for MultiPolygons
    seen.add(s.featureIndex)
    const baseName = `${prefix}${s.featureIndex}`
    const f = collection.features[s.featureIndex] || {}
    const props = f.properties || {}
    const osmId = s.id !== undefined && s.id !== null ? s.id : s.featureIndex
    const year = yearKey && props[yearKey] !== undefined ? props[yearKey] : '-'
    const type = typeKey && props[typeKey] !== undefined ? props[typeKey] : '-'
    let row = `${baseName}\t\t${osmId}\t\t${year}\t\t${type}`
    if (withCenters) {
      const c = bboxCenter({ features: [f] })
      row += `\t\t${c[1]}\t\t${c[0]}`
    }
    lines.push(row)
  }
  return lines.join('\n') + '\n'
}
